def farthest_block_with_jumps(N, K, S):
    # Check if Chef can make exactly K jumps
    if K > N or (N % 2 != K % 2):
        return -1

    # Find the initial color of the first block
    initial_color = S[0]

    # Find the farthest block Chef can reach
    farthest = 1
    for i in range(1, N):
        if S[i] != initial_color:
            if K > 1:
                farthest = i + 1
                initial_color = '1' if initial_color == '0' else '0'
                K -= 1
            else:
                break

    return farthest if K == 0 else -1

# Read input
T = int(input())
for _ in range(T):
    N, K = map(int, input().split())
    S = input()
    print(farthest_block_with_jumps(N, K, S))
